const rawBody = $json.body ?? $json;
const body = typeof rawBody === 'string' ? JSON.parse(rawBody) : rawBody;
const nickname = String(body.nickname ?? '').trim();

if (!nickname || nickname.length < 2 || nickname.length > 80) {
  throw new Error('nickname_invalid');
}

const randomPart = Math.random().toString(36).slice(2, 14);
const timePart = Date.now().toString(36);
const leadSessionId = `ce_${timePart}${randomPart}`.slice(0, 19);

return [{
  json: {
    lead_session_id: leadSessionId,
    nickname,
    fbp: body.fbp ?? null,
    fbc: body.fbc ?? null,
    fbclid: body.fbclid ?? null,
    utm_source: body.utm_source ?? null,
    utm_medium: body.utm_medium ?? null,
    utm_campaign: body.utm_campaign ?? null,
    utm_content: body.utm_content ?? null,
    utm_term: body.utm_term ?? null,
    landing_page_url: body.landing_page_url ?? null,
    status: 'started',
    received_at: new Date().toISOString()
  }
}];

const pageId = '1353563564512428';
const leadSessionId = $json.lead_session_id;

return [{
  json: {
    success: true,
    lead_session_id: leadSessionId,
    messenger_url: `https://m.me/${pageId}?ref=${encodeURIComponent(leadSessionId)}`
  }
}];
